"""Small client for the internal pricing API."""

import json
import os
import urllib.request

# Allow deployment configuration to select the service alias and credentials;
# the defaults are the current staging service.
BASE = os.environ.get("PRICING_BASE", "http://pricing-v2.internal:8081/api/v2/price")


def get_price(sku: str) -> float:
    headers = {}
    if key := os.environ.get("PRICING_KEY"):
        headers["X-Pricing-Key"] = key
    request = urllib.request.Request(f"{BASE}/{sku}", headers=headers)
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    """Return the sum of the prices returned by the pricing service."""
    total = 0.0
    for sku in skus:
        total += get_price(sku)
    return total
